algorithms.pseudocode:
function FIBER_WALK(u0, steps, statistic, observed):
    u := u0 ; tail := 0
    repeat steps times:
        pick distinct rows i, i' and distinct cols j, j' uniformly
        pick sign s in {+1, -1}
        w := u + s * B(i, i', j, j')
        if NONNEG(w): u := w                # Metropolis accept (uniform target)
        if statistic(u) >= statistic(observed): tail += 1
    return tail / steps                     # estimated exact p-value
